INSERT INTO marker_revision (marker_id, user_id, action, summary, reverts_revision_id, data, created) SELECT 798, 96, 'import', NULL, NULL, '{"title":"Link''s House","description":"This is not the actual side quest name. We need to confirm in-game. -Josh","categoryId":1935,"submapId":1901,"x":179.703125,"y":-163.765625,"z":null,"global":0,"visible":1,"tabs":["<p>So far, the only known house for sale is in Hateno Village, near the back end of the village. If players go to the area, they will see some NPCs working on a broken down house. Players can talk to them and purchase the house if they have right amount of money.<br /><br />The house price can be further dropped if players are willing to contribute 30 bundles of wood. Chopping down wood isn&rsquo;t very difficult so players should go for this option instead of spending a huge amount on buying the house. All they need to do is grab an axe and start cutting down any trees they come across.</p>\\r\\n<div id=\\"&ldquo;nativo_middle&rdquo;\\">&nbsp;To make up the rest of the money, stones and gems acquired while adventuring can be sold to various vendors. Once players have the funds and 30 bundles of wood, they can go back to the house and purchase it, giving them a place to rest at.</div>"]}', '2017-03-13 03:59:07' FROM DUAL WHERE EXISTS (SELECT 1 FROM marker WHERE id = 798 AND name = 'Link&#039;s House' AND last_updated = '2017-03-13 03:59:07') AND NOT EXISTS (SELECT 1 FROM marker_revision WHERE marker_id = 798);
INSERT INTO marker_revision (marker_id, user_id, action, summary, reverts_revision_id, data, created) SELECT 798, 15, 'edit', 'Named Hylian Homeowner as in the game; placed where the game has it (23 m away)', NULL, '{"title":"Hylian Homeowner","description":"This is not the actual side quest name. We need to confirm in-game. -Josh","categoryId":1935,"submapId":1901,"x":180.0503,"y":-163.697,"z":null,"global":0,"visible":1,"tabs":["<p>So far, the only known house for sale is in Hateno Village, near the back end of the village. If players go to the area, they will see some NPCs working on a broken down house. Players can talk to them and purchase the house if they have right amount of money.<br /><br />The house price can be further dropped if players are willing to contribute 30 bundles of wood. Chopping down wood isn&rsquo;t very difficult so players should go for this option instead of spending a huge amount on buying the house. All they need to do is grab an axe and start cutting down any trees they come across.</p>\\r\\n<div id=\\"&ldquo;nativo_middle&rdquo;\\">&nbsp;To make up the rest of the money, stones and gems acquired while adventuring can be sold to various vendors. Once players have the funds and 30 bundles of wood, they can go back to the house and purchase it, giving them a place to rest at.</div>"]}', NOW() FROM DUAL WHERE EXISTS (SELECT 1 FROM marker WHERE id = 798 AND name = 'Link&#039;s House' AND last_updated = '2017-03-13 03:59:07');
